        }
    }
}

private IEnumerator Resetgame(float time)
{
    Texture2D activeLUT = (Texture2D)colorLookup.texture.value;
    float startContribution = colorLookup.contribution.value;

    float elapsed = 0f;

    while (elapsed < time)
    {
        elapsed += Time.deltaTime;
        float pct = elapsed / time;

        colorLookup.contribution.value = Mathf.Lerp(startContribution, 0f, pct);
        colorLookup.texture.value = activeLUT;

        float w = Mathf.Lerp(startContribution, 0f, pct);
        passthroughLayer.SetColorLut(new OVRPassthroughColorLut(activeLUT, flipY: false), w);

        yield return null;
    }

    colorLookup.contribution.value = 0f;
    passthroughLayer.SetColorLut(new OVRPassthroughColorLut(activeLUT, flipY: false), 0f);

    SceneManager.LoadScene(SceneManager.GetActiveScene().buildIndex);
}

private IEnumerator SmoothFill(float targetfill, float duration)
{
    float startfill = matfill;
    float time = 0f;

    while (time < duration)
    {
        time += Time.deltaTime;
        matfill = Mathf.Lerp(startfill, targetfill, time / duration);

        if (material != null)
        {
            material.SetFloat("_Fill", matfill);
        }

        yield return null;
    }
}

public class AmmoPickup : MonoBehaviour
{
    private GameManager GM;
    [SerializeField] private AudioSource audioSource;

    private void Update()
    {
        if (GM == null)
        {
            GM = FindFirstObjectByType<GameManager>();
        }
    }

    private void OnTriggerEnter(Collider other)
    {
        if (!other.CompareTag("Player")) return;

        GM.AddMag();
        audioSource.Play();
        Destroy(gameObject);
    }
}

private void TryEjectMagazine()
{
    if (magSnapZone == null)
    {
        Debug.LogWarning("Magazine SnapZone not assigned.");
        return;
    }

    Grabbable grabbedMag = magSnapZone.HeldItem;

    if (grabbedMag != null)
    {
        magSnapZone.ReleaseAll();
        EjectSound.Play();

        Rigidbody rb = grabbedMag.GetComponent<Rigidbody>();
        if (rb != null)
        {
            rb.AddForce(transform.right * 3f + transform.up * 0.5f, ForceMode.Impulse);
        }

        Debug.Log("Magazine ejected.");
    }
}

private void HandleGearUp(InputAction.CallbackContext ctx)
{
    int next = currentGearIndex;
    if (currentGearIndex == 1) next = 0; // R -> N
    else if (currentGearIndex == 0) next = 2; // N -> 1st
    else if (currentGearIndex < gearRatios.Length - 1) next++;

    TrySetGear(next);
}

private void RemoveSpecificMask(int idToRemove)
{
    List<Mask> temp = gm.masks.ToList();
    Mask toRemove = temp.FirstOrDefault(m => m.id == idToRemove);

    if (toRemove != null)
    {
        temp.Remove(toRemove);
        gm.masks.Clear();
        temp.Reverse();
